							t.Error(err)
						}
					}
					if transactions != nil && !servingWindow && !issuanceReceipt.ByOperation[storetest.TransactionFanOutChunk].LastCommitAt.IsZero() {
						if err := storetest.ValidateReporterStressJoined(issuanceReceipt, transactions.Snapshot(), transactionOptions.Delay); err != nil {
							t.Error(err)
						}
					}
				})
			}
			mergeCeiling := issuanceBudget
			validDrainCeiling := 5 * time.Minute
			if backend == "postgres" && transactionOptions.Delay == 0 {
				mergeCeiling = 26 * time.Second
			}
			if transactionOptions.Delay == 300*time.Millisecond && (transactionOptions.DelayScope == storetest.DelayAllCommits || servingWindow) {
				if backend == "postgres" {
					mergeCeiling, validDrainCeiling = 150*time.Second, 6*time.Minute
				} else {
					mergeCeiling, validDrainCeiling = 165*time.Second, 8*time.Minute
				}
			}
			if transactionOptions.Delay > 0 && runIssue2394DelayedHTTPProcess(t, backend) {
				return
			}
			root := issue2394ServedReporterSource(t)
			opts, start := lifecycleRestartHarness(t, backend, root)
			opts.TestLLMRuntime = servedNoopLLMRuntime{}
			var selected any
			captureSelectedRuntimePersistence(t, func(p serveRuntimePersistence) {
				selected = p.deps.EventStore
			})
			process, rt := start()
			t.Cleanup(func() {
				if t.Failed() {
					t.Logf("served output:\n%s", process.outputString())
				}
			})
			runID := uuid.NewString()
			const portfolio = "portfolio-numeric-valid"
			var started struct {
				RunID string `json:"run_id"`
			}
			issue2394ReporterRPC(t, rt.Endpoint, "run.start", map[string]any{"run_id": runID, "bundle_hash": rt.BundleHash, "event_name": "portfolio.opened", "payload": map[string]any{"portfolio_id": portfolio, "threshold": 75}, "idempotency_key": uuid.NewString()}, &started)
			if started.RunID != runID {
				t.Fatalf("HTTP start changed run identity: %+v", started)
			}
			waitPublicationSiteCompletion(t, rt.ReceiverStateReader, runID)
			var metadataRaw []byte
			if err := rt.DB.QueryRow(`SELECT fields FROM entity_state WHERE run_id=$1 AND flow_instance='portfolio' ORDER BY updated_at DESC LIMIT 1`, runID).Scan(&metadataRaw); err != nil {
				t.Fatal(err)
			}
			var metadata map[string]any
			if err := json.Unmarshal(metadataRaw, &metadata); err != nil || metadata["portfolio_id"] != portfolio {
				t.Fatalf("original portfolio metadata changed: %s err=%v", metadataRaw, err)
			}
			transactions = storetest.CollectTransactions(t, selected, transactionOptions)
			t.Cleanup(func() {
				if t.Failed() {
					t.Logf("failed served reporter transaction snapshot: %+v", transactions.Snapshot())
				}
			})
			wanted := make(map[string]map[string]any)
			issuanceStarted := time.Now()
			for batch := 0; batch < 20; batch++ {
				rows := make([]map[string]any, 0, 25)
				for row := 0; row < 25; row++ {
					ordinal := batch*25 + row
					payload := map[string]any{"account_id": fmt.Sprintf("numeric-%03d", ordinal), "eng_roles": ordinal, "gem_score": float64(ordinal) + 0.25, "external_id": uuid.NewString()}
					rows = append(rows, payload)
					wanted[payload["account_id"].(string)] = payload
				}
				publishIssue2394ReporterBatch(t, rt.Endpoint, runID, portfolio, rows)
			}
			observed := waitIssue2394ReporterCursor(t, rt, runID, 500)
			var receipt storetest.TransactionSnapshot
			for deadline := time.Now().Add(5 * time.Minute); ; {
				receipt = transactions.Snapshot()
				if receipt.ByOperation[storetest.TransactionFanOutChunk].WriteCommits >= 20 {
					break
				}
				if time.Now().After(deadline) {
					t.Fatalf("missing acknowledged chunk receipt: %+v", receipt)
				}
				time.Sleep(10 * time.Millisecond)
			}
			claims, chunks := receipt.ByOperation[storetest.TransactionFanOutClaim], receipt.ByOperation[storetest.TransactionFanOutChunk]
			if claims.WriteCommits != 20 || chunks.WriteCommits != 20 || receipt.ByOperation[storetest.TransactionFanOutRelease].WriteCommits != 0 {
				t.Errorf("original 20 chunks require 20 claim + 20 atomic publication commits and no separate release: %+v", receipt)
			}
			if chunks.LastCommitAt.IsZero() || chunks.FirstCommitAt.Before(issuanceStarted) {
				t.Fatalf("commit acknowledgements missing or before first submission: %+v", chunks)
			}
			elapsed := chunks.LastCommitAt.Sub(issuanceStarted)
			if backend == "postgres" && transactionOptions.Delay == 0 {
				t.Logf("normal PostgreSQL served reporter: measured=%s original_objective=%s prior_ceiling=%s previous_ceiling=%s current_ceiling=%s", elapsed, issuanceBudget, 15*time.Second, 20*time.Second, mergeCeiling)
			}
			t.Logf("HTTP original500 first batch submission -> final durable chunk acknowledgement: %s (original_target=%s merge_ceiling=%s); cursor observed at %s; delay=%s scope=%s; transaction receipt=%+v", elapsed, issuanceBudget, mergeCeiling, observed.Sub(issuanceStarted), transactionOptions.Delay, transactionOptions.DelayScope, receipt)
			if elapsed > mergeCeiling {
				t.Errorf("original500 HTTP issuance exceeded %s merge ceiling (original target %s): %s", mergeCeiling, issuanceBudget, elapsed)
			}
			if transactionOptions.Delay > 0 && (chunks.DelayedCommits != 20 || chunks.InjectedDelay != 20*transactionOptions.Delay) {
				t.Errorf("original all-commit delay not applied to every chunk: %+v", chunks)
			}
			settledBeforeHandoff := false
			issuanceReceipt = receipt
			if servingWindow {
				if err := storetest.ValidateReporterIssuance(receipt, issuanceStarted, 20, transactionOptions.Delay); err != nil {
					t.Fatal(err)
				}
				var atCut cliapp.DiagnosticRunDiagnosisResult
				response := requestServedJSONRPCWithTimeout(t, rt.Endpoint, "run.diagnose", map[string]any{"run_id": runID}, 30*time.Second)
				if response.Error != nil {
					t.Fatalf("pre-handoff run.diagnose refused: %+v", response.Error)
				}
				if err := json.Unmarshal(response.Result, &atCut); err != nil {
					t.Fatalf("decode pre-handoff run.diagnose: %v; %s", err, response.Result)
				}
				settledBeforeHandoff = atCut.FanOut.Settled == 500 && atCut.FanOut.Unsettled == 0 && atCut.FanOut.Owed == 0
				t.Logf("pre-handoff descendant disposition: settled=%d unsettled=%d owed=%d native_settlements=%d", atCut.FanOut.Settled, atCut.FanOut.Unsettled, atCut.FanOut.Owed, receipt.ByOperation[storetest.TransactionDeliverySettle].WriteCommits)
				continuation = storetest.ReplaceTransactions(t, transactions, storetest.TransactionProbeOptions{})
			}
			drainStarted := time.Now()
			valid := waitIssue2394ReporterDiagnosisWithin(t, rt, runID, 500, validDrainCeiling)
			assertIssue2394ReporterSummary(t, valid.FanOut, runID, false)
			if servingWindow {
				if err := storetest.ValidateReporterDrain(receipt, transactions.Snapshot(), continuation.Snapshot(), settledBeforeHandoff); err != nil {
					t.Fatal(err)
				}
				t.Logf("post-issuance descendant settlement receipts: detached=%+v successor=%+v", transactions.Snapshot().ByOperation[storetest.TransactionDeliverySettle], continuation.Snapshot().ByOperation[storetest.TransactionDeliverySettle])
			}
			assertIssue2394ReporterHistory(t, rt.DB, runID)
			validEvents := assertIssue2394ReporterEvents(t, rt.Endpoint, rt.ReceiverStateReader, runID, portfolio, wanted)
			for _, id := range []string{"numeric-000", "numeric-499"} {
				assertIssue2394ReporterEventGet(t, rt.Endpoint, validEvents[id])
			}
			mixed := []map[string]any{{"account_id": "mixed-before", "eng_roles": 1, "gem_score": 1.25, "external_id": uuid.NewString()}, {"account_id": "mixed-empty-uuid", "eng_roles": 2, "gem_score": 2.25, "external_id": ""}, {"account_id": "mixed-bad-number", "eng_roles": 3, "gem_score": "not-a-number", "external_id": uuid.NewString()}, {"account_id": "mixed-after", "eng_roles": 4, "gem_score": 4.25, "external_id": uuid.NewString()}}
			publishIssue2394ReporterBatch(t, rt.Endpoint, runID, portfolio, mixed)
			waitIssue2394ReporterCursor(t, rt, runID, 504)
			final := waitIssue2394ReporterDiagnosis(t, rt, runID, 504)
			assertIssue2394ReporterSummary(t, final.FanOut, runID, true)
			assertIssue2394ReporterRejections(t, rt.DB, runID)
			wanted["mixed-before"], wanted["mixed-after"] = mixed[0], mixed[3]
			finalEvents := assertIssue2394ReporterEvents(t, rt.Endpoint, rt.ReceiverStateReader, runID, portfolio, wanted)
			for id, before := range validEvents {
				if !reflect.DeepEqual(before, finalEvents[id]) {
					t.Fatalf("mixed batch changed original valid event %s", id)
				}
			}
			for _, id := range []string{"mixed-before", "mixed-after"} {
				assertIssue2394ReporterEventGet(t, rt.Endpoint, finalEvents[id])
			}
			assertIssue2394ReporterClients(t, rt.Endpoint, rt.ReceiverStateReader, runID, final.FanOut)
			if transactionOptions.Delay > 0 {
				observed := transactions
				wantChunks := uint64(21)
				if servingWindow {
					observed, wantChunks = continuation, 1
				}
				for deadline := time.Now().Add(5 * time.Minute); observed.Snapshot().ByOperation[storetest.TransactionFanOutChunk].WriteCommits < wantChunks; {
					if time.Now().After(deadline) {
						t.Fatalf("missing mixed native receipt: %+v", observed.Snapshot())
					}
					time.Sleep(10 * time.Millisecond)
				}
				if servingWindow {
					if err := storetest.ValidateReporterContinuation(receipt, transactions.Snapshot(), continuation.Snapshot()); err != nil {
						t.Fatal(err)
					}
					t.Logf("reporter serving window: issuance=%s drain_mixed_readback=%s detached=%+v successor=%+v", elapsed, time.Since(drainStarted), transactions.Snapshot(), continuation.Snapshot())
				} else if err := storetest.ValidateReporterStress(receipt, transactions.Snapshot(), transactionOptions.Delay); err != nil {
					t.Fatal(err)
				} else {
					storetest.JoinReporterTransactions(t, transactions)
				}
			}
		})
	}
}

