			if err != nil {
				t.Fatal(err)
			}
			if child.Generation() != expected.Generation() || child.MaxAttempts != source.MaxAttempts || child.CurrentStage != "reviewing" {
				t.Fatalf("child generation or executed stage: %+v, expected %+v", child, expected)
